from math import pi

def captured_power(luminosity_w: float, radius_m: float, coverage: float) -> float:
    if radius_m <= 0 or not 0 <= coverage <= 1:
        raise ValueError("Require positive radius and coverage in [0, 1]")
    area = 4 * pi * radius_m**2
    flux = luminosity_w / area
    return flux * coverage * area

if __name__ == "__main__":
    for f in (0.1, 0.5, 1.0):
        print(f"{f:.0%}: {captured_power(3.828e26, 1.495978707e11, f):.3e} W")

from typing import Sequence

def load(areas: Sequence[float]) -> float:
    return sum(a*a for a in areas)

def optimum(total_area: float, count: int) -> tuple[list[float], float]:
    if count <= 0:
        raise ValueError("count must be positive")
    allocation = [total_area/count] * count
    return allocation, load(allocation)

if __name__ == "__main__":
    for n in (1, 2, 4, 8, 16):
        _, q = optimum(12.0, n)
        print(n, q)

def capacity(energy_j: float, cost_j: float) -> float:
    if energy_j < 0 or cost_j <= 0:
        raise ValueError("Require nonnegative energy and positive cost")
    return energy_j / cost_j

if __name__ == "__main__":
    print("operations/s:", f"{capacity(1e26, 1e-14):.0e}")
    energy = 1e30
    bit_cost = energy / 1e50
    print("bits:", f"{capacity(energy, bit_cost):.0e}")

